                                ENUM_DIV_SOURCE source,
int
mpoLen,
int
mpoSmooth,
int
rsiPeriod,
int
divPivotLen,
string
symbol =
""
,
ENUM_TIMEFRAMES
tf =
PERIOD_CURRENT
)
  {
if
(mpoLen <=
0
|| mpoSmooth <=
0
|| rsiPeriod <=
0
|| divPivotLen <=
0
)
