);
if
(symbol ==
""
)
      symbol =
_Symbol
;

   divEngine.Source = source;
   divEngine.MPO_len = mpoLen;
   divEngine.MPO_smooth = mpoSmooth;
   divEngine.RsiPeriod = rsiPeriod;
   divEngine.DivPivotLen = divPivotLen;
   divEngine.SmoothAlpha =
2.0
/ (mpoSmooth +
1.0
);
   divEngine.rsiHandle =
INVALID_HANDLE
;
if
(divEngine.Source == DIV_SRC_RSI)
     {
      divEngine.rsiHandle =
iRSI
(symbol, tf, divEngine.RsiPeriod,
