     {
PrintFormat
(
"ResizeDivergenceBuffers: ArrayResize failed, size=%d, error=%d"
,
                  size,
GetLastError
());
return
false
;
     }
if
(!
ArraySetAsSeries
(divEngine.buf_OscRaw,
true
) ||
      !
ArraySetAsSeries
(divEngine.buf_OscSmooth,
true
) ||
      !
ArraySetAsSeries
(divEngine.buf_RSI,
true
) ||
      !
ArraySetAsSeries
(divEngine.LastPivLowPriceBuffer,
true
) ||
      !
ArraySetAsSeries
(divEngine.LastPivLowOscBuffer,
true
) ||
      !
ArraySetAsSeries
(divEngine.LastPivHighPriceBuffer,
true
) ||
      !
ArraySetAsSeries
(divEngine.LastPivHighOscBuffer,
true
) ||
      !
ArraySetAsSeries
(divEngine.LastTypeBuffer,
true
) ||
      !
ArraySetAsSeries
(divEngine.BarsSinceBuffer,
true
))
     {
PrintFormat
(
"ResizeDivergenceBuffers: ArraySetAsSeries failed, error=%d"
,
GetLastError
());
return
false
;
