//+------------------------------------------------------------------+
//| Boundary Initialization function (Seed the bar at limit+1)       |
//+------------------------------------------------------------------+
void
InitDivergenceBoundaries(DivergenceEngine &divEngine,
int
limit)
  {
int
size =
ArraySize
(divEngine.buf_OscSmooth);
if
(limit +
1
>= size)
return
;
//--- The loop's first bar (i = limit) reads i+1, so limit+1 is the only bar to seed
divEngine.buf_OscRaw[limit+
1
] =
0
;
   divEngine.buf_OscSmooth[limit+
1
] =
0
;
   divEngine.LastTypeBuffer[limit+
1
] =
0
;
   divEngine.BarsSinceBuffer[limit+
1
] = DIV_NO_BARS;
//--- Any real price passes the price sentinels and no oscillator value passes the
//--- oscillator ones, so the first pivot becomes a reference, never a divergence
divEngine.LastPivLowPriceBuffer[limit+
1
] =
DIV_NO_LOW_PRICE
;
   divEngine.LastPivLowOscBuffer[limit+
1
] =
DIV_NO_LOW_OSC
;
   divEngine.LastPivHighPriceBuffer[limit+
1
] =
DIV_NO_HIGH_PRICE
;
   divEngine.LastPivHighOscBuffer[limit+
1
] =
DIV_NO_HIGH_OSC
;
  }
InitDivergenceBoundaries() runs on every pass, before the per-bar loop. That loop starts at i = limit, and CalculateOscillator() and DetectDivergence() both read i + 1, so the first bar processed reads index limit + 1. The function writes that one index and nothing else, filling it with the
sentinel values
: no divergence, a bar count of DIV_NO_BARS, and placeholder pivot references. Any real price passes the price half of the divergence test against those placeholders, and no real oscillator value passes the oscillator half, so a pivot compared against them is only stored as the reference for the next one. This follows the original SuperTrend boundary-seeding pattern. The difference is that it now lives in the engine, not duplicated in every consumer.
Phase 2: The Oscillator Module
The Oscillator phase converts raw price data into the smoothed oscillator used by the divergence logic. When RSI is selected, UpdateDivergenceRSI() copies the RSI indicator buffer into the engine's internal array before the main calculation loop:
//+------------------------------------------------------------------+
//| Phase 2/4 — OSCILLATOR                                           |
//+------------------------------------------------------------------+
//+------------------------------------------------------------------+
//| Update RSI before calculation loop (If using RSI as source)      |
//+------------------------------------------------------------------+
bool
UpdateDivergenceRSI(DivergenceEngine &divEngine,
int
limit)
  {
if
(divEngine.Source == DIV_SRC_RSI && divEngine.rsiHandle !=
INVALID_HANDLE
)
     {
// Ensure we have enough bars calculated
int
barsCalc =
BarsCalculated
(divEngine.rsiHandle);
if
(barsCalc < limit +
2
)
        {
Print
(
"RSI is not ready: BarsCalculated = "
, barsCalc,
", needed = "
, limit+
2
);
return
false
;
        }
double
tempRSI[];
if
(!
ArraySetAsSeries
(tempRSI,
true
))
        {
PrintFormat
(
"ArraySetAsSeries(tempRSI) failed, error=%d"
,
GetLastError
());
return
false
;
        }
int
copied =
CopyBuffer
(divEngine.rsiHandle,
0
,
0
, limit +
2
, tempRSI);
if
(copied < limit +
2
)
        {
Print
(
"Failed to copy enough RSI values. Copied "
, copied,
", needed "
, limit+
2
);
return
false
;
        }
// Clear the whole target range first
ArrayFill
(divEngine.buf_RSI,
0
, limit +
2
,
0.0
);
// Copy only up to limit+1
int
max_idx = (
int
)
MathMin
(limit +
1
, copied -
1
);
for
(
int
k =
0
; k <= max_idx; k++)
         divEngine.buf_RSI[k] = tempRSI[k];
return
true
;
     }
return
true
;
  }
CalculateOscillator() is then called for each processed bar. Its job is to calculate the selected raw oscillator and apply the same exponential smoothing used by the original implementation:
//+------------------------------------------------------------------+
//| Compute the smoothed oscillator value for the selected source    |
//+------------------------------------------------------------------+
void
CalculateOscillator(DivergenceEngine &divEngine,
int
i,
const
double
&open[],
const
double
&close[],
double
DivPoint)
  {
int
size = (
int
)
MathMin
(
MathMin
(
ArraySize
(open),
ArraySize
(close)),
MathMin
(
ArraySize
(divEngine.buf_OscRaw),
ArraySize
(divEngine.buf_OscSmooth))
              );
//--- Guard
if
(i <
0
|| i >= size)
return
;
if
(divEngine.Source == DIV_SRC_MPO)
     {
//--- Check if we have enough bars ahead for MPO
if
(i + divEngine.MPO_len > size)
        {
// Not enough data: carry forward previous value if possible, else set to 0
if
(i +
1
< size)
           {
            divEngine.buf_OscRaw[i] = divEngine.buf_OscRaw[i+
1
];
            divEngine.buf_OscSmooth[i] = divEngine.buf_OscSmooth[i+
1
];
           }
else
{
            divEngine.buf_OscRaw[i] =
0
;
            divEngine.buf_OscSmooth[i] =
0
;
           }
return
;
        }
double
rollingSum =
0
;
double
sumBodies =
0
;
for
(
int
k =
0
; k < divEngine.MPO_len; k++)
         sumBodies +=
MathAbs
(close[i+k] - open[i+k]);
double
avgBody = (sumBodies >
0
) ? sumBodies / divEngine.MPO_len : DivPoint;
for
(
int
k =
0
; k < divEngine.MPO_len; k++)
        {
int
idx = i + k;
double
body =
MathAbs
(close[idx] - open[idx]);
double
dir = (close[idx] > open[idx]) ?
1.0
: (close[idx] < open[idx]) ? -
1.0
:
0.0
;
double
weight = (avgBody >
0
) ? body / avgBody :
1.0
;
         rollingSum += (dir * weight);
        }
      divEngine.buf_OscRaw[i] = (rollingSum / (divEngine.MPO_len *
2.0
)) *
100.0
;
     }
else
// RSI source
{
//--- Ensure buf_RSI has data at i
if
(i <
ArraySize
(divEngine.buf_RSI))
         divEngine.buf_OscRaw[i] = divEngine.buf_RSI[i];
else
divEngine.buf_OscRaw[i] =
0
;
     }
//--- Apply Smoothing
if
(i +
1
< size)
      divEngine.buf_OscSmooth[i] = (divEngine.buf_OscRaw[i] * divEngine.SmoothAlpha) + (divEngine.buf_OscSmooth[i+
1
] * (
1.0
- divEngine.SmoothAlpha));
else
divEngine.buf_OscSmooth[i] = divEngine.buf_OscRaw[i];
// fallback
}
The MPO4 branch retains the weighted-body calculation introduced in the
first part
of the series: each candle's directional body is weighted against the average body size of the window, summed over
MPO_len
bars, and scaled into the oscillator's range. The main addition here is protection against insufficient look-ahead data. Because the engine processes bars backwards, the oldest bars in a limited history may not have a complete
MPO_len
window. Rather than produce a distorted value, the calculation carries forward the previous value when possible.
The RSI branch does not calculate anything itself. It reads from
buf_RSI
, which was populated by UpdateDivergenceRSI(). Both sources then pass through the same exponential smoothing step controlled by SmoothAlpha. This gives
Phase 3
a single oscillator buffer to work with, regardless of whether the source is MPO4 or RSI.
Phase 3: The Divergence Module
On each bar, DetectDivergence() does two things: it carries forward prior state/pivots and then checks whether the current window confirms a new pivot.
//+------------------------------------------------------------------+
//| Phase 3/4 — DIVERGENCE                                           |
//+------------------------------------------------------------------+
void
DetectDivergence(DivergenceEngine &divEngine,
int
i,
const
double
&high[],
const
double
&low[],
int
limit)
  {
int
size = (
int
)
MathMin
(
MathMin
(
ArraySize
(high),
ArraySize
(low)),
MathMin
(
MathMin
(
ArraySize
(divEngine.LastTypeBuffer),
ArraySize
(divEngine.BarsSinceBuffer)),
MathMin
(
MathMin
(
ArraySize
(divEngine.LastPivLowPriceBuffer),
ArraySize
(divEngine.LastPivLowOscBuffer)),
MathMin
(
ArraySize
(divEngine.LastPivHighPriceBuffer),
ArraySize
(divEngine.LastPivHighOscBuffer))
                    )
                 )
              );
//--- Guard
if
(i <
0
|| i >= size)
return
;
if
(i +
1
< size)
     {
//--- Inherit state
divEngine.LastTypeBuffer[i]         = divEngine.LastTypeBuffer[i+
1
];
      divEngine.BarsSinceBuffer[i]        = divEngine.BarsSinceBuffer[i+
1
] +
1
;
      divEngine.LastPivLowPriceBuffer[i]  = divEngine.LastPivLowPriceBuffer[i+
1
];
      divEngine.LastPivLowOscBuffer[i]    = divEngine.LastPivLowOscBuffer[i+
1
];
      divEngine.LastPivHighPriceBuffer[i] = divEngine.LastPivHighPriceBuffer[i+
1
];
      divEngine.LastPivHighOscBuffer[i]   = divEngine.LastPivHighOscBuffer[i+
1
];
     }
else
{
//--- Fallback default if at the absolute edge of the array
divEngine.LastTypeBuffer[i]         =
0
;
      divEngine.BarsSinceBuffer[i]        = DIV_NO_BARS;
      divEngine.LastPivLowPriceBuffer[i]  = DIV_NO_LOW_PRICE;
      divEngine.LastPivLowOscBuffer[i]    = DIV_NO_LOW_OSC;
      divEngine.LastPivHighPriceBuffer[i] = DIV_NO_HIGH_PRICE;
      divEngine.LastPivHighOscBuffer[i]   = DIV_NO_HIGH_OSC;
     }
int
pIdx = i + divEngine.DivPivotLen;
//--- Check that we have enough bars on both sides of the pivot and that pIdx is within array
if
(pIdx - divEngine.DivPivotLen >=
0
&& pIdx + divEngine.DivPivotLen < size && pIdx < size)
     {
bool
isPivLow =
true
;
bool
isPivHigh =
true
;
for
(
int
k =
1
; k <= divEngine.DivPivotLen; k++)
        {
// Strict pivot. For non-strict (allow equal), use <= and >= accordingly.
if
(!(divEngine.buf_OscSmooth[pIdx] < divEngine.buf_OscSmooth[pIdx+k] && divEngine.buf_OscSmooth[pIdx] < divEngine.buf_OscSmooth[pIdx-k]))
            isPivLow =
false
;
if
(!(divEngine.buf_OscSmooth[pIdx] > divEngine.buf_OscSmooth[pIdx+k] && divEngine.buf_OscSmooth[pIdx] > divEngine.buf_OscSmooth[pIdx-k]))
            isPivHigh =
false
;
        }
//--- Process Bullish Pivot
if
(isPivLow)
        {
if
(low[pIdx] < divEngine.LastPivLowPriceBuffer[pIdx] && divEngine.buf_OscSmooth[pIdx] > divEngine.LastPivLowOscBuffer[pIdx])
           {
            divEngine.LastTypeBuffer[i] =
1
;
            divEngine.BarsSinceBuffer[i] =
0
;
           }
         divEngine.LastPivLowPriceBuffer[i] = low[pIdx];
         divEngine.LastPivLowOscBuffer[i] = divEngine.buf_OscSmooth[pIdx];
        }
//--- Process Bearish Pivot
if
(isPivHigh)
        {
if
(high[pIdx] > divEngine.LastPivHighPriceBuffer[pIdx] && divEngine.buf_OscSmooth[pIdx] < divEngine.LastPivHighOscBuffer[pIdx])
           {
            divEngine.LastTypeBuffer[i] = -
1
;
            divEngine.BarsSinceBuffer[i] =
0
;
           }
         divEngine.LastPivHighPriceBuffer[i] = high[pIdx];
         divEngine.LastPivHighOscBuffer[i] = divEngine.buf_OscSmooth[pIdx];
        }
     }
  }
The pivot itself sits
DivPivotLen
bars behind the current processing index, at pIdx. A pivot low is confirmed when the oscillator value there is lower than every value within
DivPivotLen
bars on both sides. A pivot high uses the opposite condition. This is the same symmetric-window pivot detection introduced in
Part II
